import { TypedEventBus } from "../../../base/EventComponent/TypedEventBus";
import { SubscriptionBag } from "../../../base/EventComponent/SubscriptionBag";
import { TableListModel } from "./TableListModel";
import { TableIdentity, TableStats, TableSeatState } from "./TableListTypes";

export type TableFilter = "all" | "empty";

/** 渲染用的單桌資料：身分 + 統計（統計可能還沒拉到，允許 null） */
export interface TableListEntry {
    identity: TableIdentity;
    stats: TableStats | null;
}

export interface TableListViewModelEvents {
    /** 篩選/排序後的清單有變動（新增/移除桌、統計更新、篩選條件變更皆會觸發） */
    entriesChanged: { entries: TableListEntry[] };
}

/**
 * TableListViewModel（快取篩選層）
 *
 * 訂閱 TableListModel 的事件，把身分（identities）跟統計（stats）用 tableId
 * join 起來，套用篩選條件，快取成 View 直接可用的 entries——View 只讀這層，
 * 不直接碰 TableListModel。排序規則目前沒有定案（待產品需求），先只做篩選。
 *
 * 是獨立生命週期的物件（非 Cocos Component），呼叫端負責在畫面關閉時呼叫 dispose()。
 */
export class TableListViewModel {
    readonly events = new TypedEventBus<TableListViewModelEvents>();

    private readonly subscriptions = new SubscriptionBag();
    private filter: TableFilter = "all";
    private entries: TableListEntry[] = [];

    constructor(private readonly model: TableListModel) {
        this.subscriptions.add(model.events.on("identitiesChanged", () => this.recompute()));
        this.subscriptions.add(model.events.on("statsChanged", () => this.recompute()));
        this.subscriptions.add(model.events.on("tableRemoved", () => this.recompute()));
        this.recompute();
    }

    setFilter(filter: TableFilter): void {
        if (this.filter === filter) return;
        this.filter = filter;
        this.recompute();
    }

    getFilter(): TableFilter {
        return this.filter;
    }

    /** 目前篩選後的清單快照 */
    getEntries(): TableListEntry[] {
        return this.entries;
    }

    dispose(): void {
        this.subscriptions.dispose();
    }

    private recompute(): void {
        const identities = this.model.getAllIdentities();
        const filtered = this.filter === "empty" ? identities.filter((identity) => identity.seatState === TableSeatState.Empty) : identities;

        this.entries = filtered.map((identity) => ({
            identity,
            stats: this.model.getStats(identity.tableId) ?? null,
        }));

        this.events.emit("entriesChanged", { entries: this.entries });
    }
}
