import { _decorator, Button, Component, Label, Node, tween, Tween, Vec3 } from 'cc';
import { GAME_EVENT_ID, GAME_EVENT_TYPE, gameRuntimeEventBus } from '../../core/framework/Runtime/Events/GameRuntimeEventBus';
import StoreManager from '../../core/framework/Runtime/Store/StoreManager';
import AppAudio from '../../core/base/audio/AppAudio';
import { EFFECTSMAP } from '../AudioConfig';

const { ccclass, property } = _decorator;

@ccclass('slot/1001/BuyFeaturePopupView')
export class BuyFeaturePopupView extends Component {
    @property(Node)
    popup: Node = null!;

    @property(Label)
    prizeLabel: Label = null!;

    @property(Label)
    betLabel: Label = null!;

    @property(Button)
    buyBtn: Button = null!;

    @property(Button)
    closeBtn: Button = null!;

    @property(Button)
    minusBtn: Button = null!;

    @property(Button)
    plusBtn: Button = null!;

    @property(Node)
    mask: Node = null!;

    private disposers: Array<() => void> = [];
    private mult = 0;

    protected override onLoad(): void {
        this.buyBtn.node.on(Button.EventType.CLICK, this.onBuy, this);
        this.closeBtn.node.on(Button.EventType.CLICK, this.onCancel, this);
        this.minusBtn.node.on(Button.EventType.CLICK, this.onMinus, this);
        this.plusBtn.node.on(Button.EventType.CLICK, this.onPlus, this);
        this.mask?.on(Node.EventType.TOUCH_END, this.onCancel, this);

        const gameStore = StoreManager.getInstance().getGameStore();
        this.disposers.push(
            gameRuntimeEventBus.on(GAME_EVENT_TYPE.BUY_FEATURE_DATA_CHANGED, (event) => {
                if (event.eventId === GAME_EVENT_ID.BUY_FEATURE_DATA_CHANGED && event.data) this.show(event.data);
            })
        );
        this.disposers.push(
            gameRuntimeEventBus.on(GAME_EVENT_TYPE.BUY_FEATURE_CLOSE_CHANGED, (event) => {
                if (event.eventId === GAME_EVENT_ID.BUY_FEATURE_CLOSE_CHANGED && event.requested) this.close();
            })
        );
        this.disposers.push(
            gameRuntimeEventBus.on(GAME_EVENT_TYPE.BET_BALANCE_CHANGED, (event) => {
                if (event.eventId === GAME_EVENT_ID.BET_BALANCE_CHANGED) this.refresh();
            })
        );

        const data = gameStore.buyFeatureData;
        if (data) this.show(data);
    }

    private show(data: { prefix: string; amount: string; mult: number }): void {
        this.mult = data.mult;
        this.refresh();
        this.playEnter();
    }

    private refresh(): void {
        const store = StoreManager.getInstance();
        const bet = store.getModel('TemplateStore').betBalance;
        const format = store.getGameStore().formatAmount;
        this.betLabel.string = format(bet);
        this.prizeLabel.string = format(bet * this.mult);
    }

    private playEnter(): void {
        const n = this.popup;
        Tween.stopAllByTarget(n);
        n.setScale(0, 0, 1);
        tween(n)
            .to(0.166, { scale: new Vec3(1.2, 1.2, 1) }, { easing: 'sineInOut' })
            .to(0.167, { scale: new Vec3(0.95, 0.95, 1) }, { easing: 'sineInOut' })
            .to(0.167, { scale: new Vec3(1, 1, 1) }, { easing: 'sineInOut' })
            .start();
    }

    private close(): void {
        const n = this.popup;
        Tween.stopAllByTarget(n);
        tween(n)
            .to(0.166, { scale: new Vec3(1.05, 1.05, 1) }, { easing: 'sineInOut' })
            .to(0.167, { scale: new Vec3(0, 0, 1) }, { easing: 'sineInOut' })
            .call(() => {
                if (this.node?.isValid) StoreManager.getInstance().getGameStore().completeBuyFeatureClose();
            })
            .start();
    }

    private onBuy(): void {
        StoreManager.getInstance().getGameStore().fireBuyFeatureConfirm();
    }
    private onCancel(): void {
        StoreManager.getInstance().getGameStore().fireBuyFeatureCancel();
    }
    private onMinus(): void {
        AppAudio.getInstance().playEffect(EFFECTSMAP.BET_CHANGE);
        StoreManager.getInstance().getModel('TemplateStore').minusBetLevel();
    }
    private onPlus(): void {
        AppAudio.getInstance().playEffect(EFFECTSMAP.BET_CHANGE);
        StoreManager.getInstance().getModel('TemplateStore').addBetLevel();
    }

    protected override onDestroy(): void {
        this.disposers.forEach((d) => d());
        this.disposers = [];
        if (this.popup) Tween.stopAllByTarget(this.popup);
    }
}
