import { GameNetHandler } from '../../../framework/Runtime/Net/GameNetHandler';
import type { SlotApiBetDetailResponse, SlotApiBetHistoryResponse, SlotApiGameInfoResponse, SlotApiGameStateResponse, SlotApiJackpotPoolSnapshot, SlotApiSpinResponse } from './SlotApiTypes';
import { SLOT_API_RESPONSE_TYPE } from './SlotApiTypes';
import { toLegacySlotConfigData } from './SlotResponseAdapter';
import type { BetHistoryDetail, BetHistoryPage } from '../../Domain/BetHistory';
import { SlotHistoryMapper } from '../Net/SlotHistoryMapper';
import { resolveSlotGridLayout } from '../Net/GridLayoutConfig';
import type { SlotGridLayout } from '../../Domain/SlotGrid';

interface SlotApiGameResponseStore {
    readonly slotLayout: SlotGridLayout;
    setSpinData(payload: SlotApiSpinResponse): void;
    setRoundId(operationId: string): void;
    setGameInfoData(payload: SlotApiGameInfoResponse): void;
    setSlotLayout(source: { cols: number; rows: number }): void;
    setGameStateData(payload: SlotApiGameStateResponse): void;
    setConfigData(configData: ReturnType<typeof toLegacySlotConfigData>): void;
    setHistoryData(history: BetHistoryPage): void;
    setJackpotPoolData(payload: SlotApiJackpotPoolSnapshot): void;
}

interface SlotApiRequestState {
    setIsUpdate(value: boolean): void;
}

export class SlotSpinResponseHandler extends GameNetHandler<SlotApiSpinResponse> {
    public readonly key = SLOT_API_RESPONSE_TYPE.SLOT_SPIN_RESPONSE;

    constructor(
        private readonly gameStore: SlotApiGameResponseStore,
        private readonly requestState: SlotApiRequestState
    ) {
        super();
    }

    public handle(payload: SlotApiSpinResponse): void {
        this.gameStore.setSpinData(payload);
        this.gameStore.setRoundId(payload.operation_id);
        this.requestState.setIsUpdate(true);
    }
}

export class GetGameInfoResponseHandler extends GameNetHandler<SlotApiGameInfoResponse> {
    public readonly key = SLOT_API_RESPONSE_TYPE.GET_GAME_INFO_RESPONSE;

    constructor(private readonly gameStore: SlotApiGameResponseStore) {
        super();
    }

    public handle(payload: SlotApiGameInfoResponse): void {
        this.gameStore.setSlotLayout(payload);
        this.gameStore.setGameInfoData(payload);
        this.gameStore.setConfigData(toLegacySlotConfigData(payload, this.gameStore.slotLayout));
    }
}

export class GetGameStateResponseHandler extends GameNetHandler<SlotApiGameStateResponse> {
    public readonly key = SLOT_API_RESPONSE_TYPE.GET_GAME_STATE_RESPONSE;

    constructor(private readonly gameStore: SlotApiGameResponseStore) {
        super();
    }

    public handle(payload: SlotApiGameStateResponse): void {
        this.gameStore.setGameStateData(payload);
    }
}

export class GetBetHistoryResponseHandler extends GameNetHandler<SlotApiBetHistoryResponse> {
    public readonly key = SLOT_API_RESPONSE_TYPE.GET_BET_HISTORY_RESPONSE;

    constructor(
        private readonly gameStore: SlotApiGameResponseStore,
        private readonly requestState: SlotApiRequestState
    ) {
        super();
    }

    public handle(payload: SlotApiBetHistoryResponse): void {
        const mapper = new SlotHistoryMapper(this.gameStore.slotLayout);
        this.gameStore.setHistoryData(mapper.toBetHistoryPage(payload));
        this.requestState.setIsUpdate(false);
    }
}

/** 三種 Jackpot snapshot 都覆寫完整四階資料 */
export class JackpotPoolResponseHandler extends GameNetHandler<SlotApiJackpotPoolSnapshot> {
    constructor(
        public readonly key: string,
        private readonly gameStore: SlotApiGameResponseStore
    ) {
        super();
    }

    public handle(payload: SlotApiJackpotPoolSnapshot): void {
        this.gameStore.setJackpotPoolData(payload);
    }
}

export class GetBetDetailResponseHandler extends GameNetHandler<SlotApiBetDetailResponse> {
    public readonly key = SLOT_API_RESPONSE_TYPE.GET_BET_DETAIL_RESPONSE;

    constructor(
        private readonly cache: Map<string, BetHistoryDetail>,
        private readonly gameStore: Pick<SlotApiGameResponseStore, 'slotLayout'>
    ) {
        super();
    }

    public handle(payload: SlotApiBetDetailResponse): void {
        const firstGrid = payload.round_result.Main[0]?.Grid;
        const layout = firstGrid ? resolveSlotGridLayout(firstGrid, this.gameStore.slotLayout) : this.gameStore.slotLayout;
        const mapper = new SlotHistoryMapper(layout);
        this.cache.set(payload.summary.operation_id, mapper.toBetHistoryDetail(payload));
    }
}
