import { _decorator, Label, Sprite, SpriteFrame, Node } from 'cc';
import { TemplateView as CoreTemplateView } from '../../core/framework/View/TemplateView/TemplateView';
import { GameStateKey } from '../../core/slot/Framework/Component/GameStateKey';
import AppAnimation from '../../core/framework/Framework/Animation/AppAnimation';

const { ccclass, property } = _decorator;

@ccclass('slot/1001/TemplateView')
export class TemplateView extends CoreTemplateView {
    // test
    @property(SpriteFrame)
    spinBtnDefaultSprite: SpriteFrame = null!;

    @property(SpriteFrame)
    spinBtnSpinningSprite: SpriteFrame = null!;

    @property(SpriteFrame)
    spinBtnAutoSprite: SpriteFrame = null!;

    @property(SpriteFrame)
    spinBtnFeatureSprite: SpriteFrame = null!;

    private FGCounter: Node | null = null;

    override onLoad() {
        this.init();
        super.onLoad();
        this.assetBundle.getSpriteFrame('main_btn_pause').then((frame) => {
            this._pauseIconSpriteFrame = frame;
        });
    }
    init() {
        if (!this.FGCounter) this.FGCounter = this.spinBtn.node.getChildByName('FGCounter');
    }

    private setSpinBtnSprite(frame: SpriteFrame | null): void {
        if (!frame) return;
        const sprite = this.spinArrowSprite?.getComponent(Sprite);
        if (sprite) sprite.spriteFrame = frame;
    }

    override setFgCounterVisible(status: boolean) {
        if (this.FGCounter) this.FGCounter.active = status;

        const autoTimes = this.autoSpinStatus?.getChildByName('AutoTimes');
        const infinite = this.autoSpinStatus?.getChildByName('Infinite');
        if (autoTimes) autoTimes.active = !status && !infinite?.active;
    }

    // override setDefaultMode(): void {
    //     super.setDefaultMode();
    //     this.setSpinBtnSprite(this.spinBtnDefaultSprite);
    // }

    /**
     * spin 轉圈的動效
     * @param fadeOpacity setAutoSpinMode 呼叫時需要在轉圈尾聲把箭頭淡出
     */
    private _playSpinAction(callBack?: () => void, fadeOpacity: boolean = false) {
        if (this.spinTween) {
            callBack?.();
            return;
        }
        this.spinTween = AppAnimation.playSpinArrow(this.spinArrowSprite, { fadeOpacity }, callBack);
    }

    override setSpinMode() {
        //Layout
        this.setSpinFrameVisible(true);
        this.setBetFrameVisible(true);
        this._playSpinAction(() => {
            //個別按鈕
            this.setSpinArrowStatus(true);
            this.setSpinStopStatus(false);
            this.setAutoSpinStatus(false);
            this.setInfiniteVisible(false);
        });
    }

    override setAutoSpinMode(times?: number | string) {
        this._playSpinAction(() => {
            this.playAutoSpinAction(times);
            //Layout
            this.setSpinFrameVisible(true);
            this.setBetFrameVisible(true);
            //個別按鈕
            this.setSpinArrowStatus(false);
            this.setSpinStopStatus(false);
            this.setAutoSpinStatus(true);
        }, true);
    }

    /** FG 狀態下 spin 按鈕 */
    // override setFeatureMode(): void {
    //     this.setSpinFrameVisible(true);
    //     this.setBetFrameVisible(false);
    //     this.setSpinBtnSprite(this.spinBtnFeatureSprite);
    // }

    // autoSpin pause 圖示
    private _pauseIcon: Node | null = null;
    private _pauseIconSpriteFrame: SpriteFrame | null = null;

    private async _ensurePauseIcon(): Promise<Node> {
        if (this._pauseIcon?.isValid) return this._pauseIcon;
        const n = new Node('pauseIcon');
        this._pauseIcon = n;
        n.layer = this.autoArrowSprite.layer;
        this.autoArrowSprite.parent.addChild(n);
        const frame = this._pauseIconSpriteFrame ?? (await this.assetBundle.getSpriteFrame('main_btn_pause'));
        // 等待期間節點可能已被銷毀 這裡補一次有效性檢查
        if (n.isValid) n.addComponent(Sprite).spriteFrame = frame;
        return n;
    }

    override async playAutoSpinAction(_speed?): Promise<void> {
        this.autoArrowSprite.active = true;
        (await this._ensurePauseIcon()).active = true;
    }
    override async stopAutoSpinAction() {
        if (this._pauseIcon?.isValid) this._pauseIcon.active = false;
        this.autoArrowSprite.active = false;
    }

    // 進出 FG 模式 覆寫
    override setGameMode(gameMode: GameStateKey): void {
        let isFg = gameMode === GameStateKey.FG;
        this.setFgCounterVisible(isFg);
        if (isFg) {
            this.setSpinArrowStatus(false);
            this.setSpinStopStatus(false);
            this.setAutoSpinStatus(true);
        }
    }

    // FG 局數倒數 覆寫
    override updateFgRound(remaining: number, total: number): void {
        const counterNode = this.FGCounter;
        if (!counterNode) return;
        const visible = total > 0 && remaining > 0;
        counterNode.active = visible;
        if (visible) counterNode.getComponent(Label).string = `${String(remaining).padStart(2, '0')}`;
    }
}
