import { TypedEventBus } from "../../../base/EventComponent/TypedEventBus";

export enum ReelState {
    IDLE,
    BEGIN,
    LOOP,
    STOPPING,
    END
}

/** ReelModel 是每個 reel view 各自持有的實例，state 變化只跟該實例有關，
 *  故比照 SlotMachineModel 用自己的 TypedEventBus，不共用全域 gameRuntimeEventBus */
export interface ReelModelEvents {
    stateChanged: { previousState: ReelState; state: ReelState };
    /** reel 完全停止（回到 IDLE）通知，payload 是 reelIndex */
    stopped: number;
    /** instantStop 用：通知 view 跳過動畫直接 snap 到該 rng */
    forceSnap: number;
}

export class ReelModel {
    readonly events = new TypedEventBus<ReelModelEvents>();

    private _state: ReelState = ReelState.IDLE;
    get state(): ReelState { return this._state; }
    setState(state: ReelState): void {
        const previousState = this._state;
        if (previousState === state) return;
        this._state = state;
        this.events.emit("stateChanged", { previousState, state });
    }

    private _currentRng: number = 0;
    get currentRng(): number { return this._currentRng; }
    setCurrentRng(currentRng: number): void { this._currentRng = currentRng; }

    private _finalRng: number = -1;
    get finalRng(): number { return this._finalRng; }
    setFinalRng(finalRng: number): void { this._finalRng = finalRng; }

    private _requestStop: boolean = false;
    get requestStop(): boolean { return this._requestStop; }
    setRequestStop(requestStop: boolean): void { this._requestStop = requestStop; }

    reelIndex: number = 0;

    /** 保留建構子參數是為了相容 SlotMachineModel 裡 `new ReelModel({})` 的舊呼叫方式 */
    constructor(_props?: unknown) {}

    spin(): void {
        this.setState(ReelState.BEGIN);
        this.setRequestStop(false);
        this.setFinalRng(-1);
    }

    stop(rng: number): void {
        this.setFinalRng(rng);
        this.setRequestStop(true);
    }

    onStopped(): void {
        this.setState(ReelState.IDLE);
        this.events.emit("stopped", this.reelIndex);
    }
}
