import { _decorator, Component } from 'cc';
import { EFFECTSMAP } from '../../../core/slot/Common/SOUNDMAP';
import AppAudio from '../../../core/base/audio/AppAudio';
const { ccclass, property } = _decorator;

@ccclass('slot/1001/CommonPopView')
export class CommonPopView extends Component {
    onStart() {
        AppAudio.getInstance().playEffect(EFFECTSMAP.INTRO_POPUP);
    }
    onExit() {
        AppAudio.getInstance().playEffect(EFFECTSMAP.INTRO_CLOSE);
        this.node.parent.destroy();
    }
}
