import { Component, Constructor, instantiate, js, Node, Prefab } from 'cc';
import { PopupBase } from './PopupBase';

type PopupManagerState = {
    defaultLayer: Node | null;
    stack: PopupBase[];
};

const STATE_KEY = '__SLOT_POPUP_MANAGER_STATE__';

function getState(): PopupManagerState {
    const scope = globalThis as typeof globalThis & { [STATE_KEY]?: PopupManagerState };
    return scope[STATE_KEY] ??= { defaultLayer: null, stack: [] };
}

/**
 * PopupManager（模組級單例）
 *
 * 統一開關所有繼承 PopupBase 的彈窗，取代各遊戲各自手刻的開關邏輯
 * （比照 lobby ViewManager 的 Stack 模式精神，但只服務 PopupBase 這條線，
 * 不是完整的 view/singleton 管理系統，那是 lobby 專用的，游戲端不需要那麼複雜）。
 *
 * - `open()` 從 prefab 產生一個新彈窗實例，掛進指定層（或 setLayer() 設定的
 *   預設層），push 進堆疊最上層。
 * - 每個彈窗一律是堆疊模式：`close()` 直接銷毀節點並移出堆疊，沒有 lobby
 *   ViewManager 那種 Singleton（只隱藏不銷毀）模式——PopupBase 系列彈窗
 *   本來就是「開一次、關掉就沒了」，不需要重用節點快取。
 * - `PopupBase.close()`／關閉鈕／背景遮罩點擊關閉，最終都會呼叫這裡的
 *   `closeNode()`，堆疊狀態永遠正確，不用另外同步。
 */
export class PopupManager {
    /** 進場景/遊戲時呼叫一次，指定彈窗預設要掛在哪個節點底下（例如 popupRoot） */
    static setLayer(node: Node): void {
        getState().defaultLayer = node;
    }

    /**
     * 從 prefab 開一個彈窗，疊在堆疊最上層。popupClass 是要拿的元件類別
     * （例如 AutoPlayPopup），prefab 根節點上要掛著這個元件，找不到就直接
     * 銷毀節點並回傳 null（同 lobby ViewManager.showPrefab() 的錯誤處理）。
     */
    static open<T extends PopupBase>(prefab: Prefab, popupClass: Constructor<T>, layer?: Node): T | null {
        const node = instantiate(prefab);
        // 不同子遊戲 Bundle 會各自編譯一份相同 class。切換遊戲後，prefab 上的
        // 元件與目前模組的 constructor 可能不是同一個物件，需以 ccclass 名稱兜底。
        const className = js.getClassName(popupClass);
        const popup = node.getComponent(popupClass) ?? node.components.find((component: Component) => {
            return js.getClassName(component) === className;
        }) as T | undefined;
        if (!popup) {
            console.warn(`[PopupManager] prefab "${prefab.name}" 上找不到 ${popupClass.name} 元件`);
            node.destroy();
            return null;
        }

        const state = getState();
        const mountLayer = layer ?? state.defaultLayer;
        if (!mountLayer) {
            console.warn('[PopupManager] 沒有可掛載的層級（尚未呼叫 setLayer()，也沒有傳入 layer 參數），彈窗不會顯示');
            node.destroy();
            return null;
        }
        mountLayer.addChild(node);

        state.stack.push(popup);
        return popup;
    }

    /** PopupBase.close() 內部呼叫，同時負責從堆疊移除、銷毀節點——不要直接呼叫 node.destroy() 略過這裡 */
    static closeNode(node: Node): void {
        const stack = getState().stack;
        const index = stack.findIndex((p) => p.node === node);
        if (index !== -1) stack.splice(index, 1);
        if (node.isValid) node.destroy();
    }

    /** 關閉堆疊最上層彈窗 */
    static closeTop(): void {
        const stack = getState().stack;
        const top = stack[stack.length - 1];
        if (top) this.closeNode(top.node);
    }

    /** 關閉所有目前開著的彈窗 */
    static closeAll(): void {
        const stack = getState().stack;
        while (stack.length > 0) {
            this.closeNode(stack[stack.length - 1].node);
        }
    }

    /** 目前堆疊最上層的彈窗實例，沒有開任何彈窗則為 null */
    static getTop(): PopupBase | null {
        const stack = getState().stack;
        return stack[stack.length - 1] ?? null;
    }

    /** 目前開著的彈窗數量 */
    static get count(): number {
        return getState().stack.length;
    }
}
