import type { SlotApiAward, SlotApiFreeMultiplier, SlotApiJackpotTier, SlotApiRoundResult, SlotApiSpinResponse, SlotApiStep } from '../Common/SlotApiTypes';
import type { SlotAward, SlotAwardPosition, SlotFreeMultiplierStep, SlotJackpotResult, SlotJackpotTier, SlotRoundResult, SlotRoundSteps, SlotRoundStep } from '../../Domain/SlotRound';
import type { SlotGridLayout } from '../../Domain/SlotGrid';
import { SlotGridDecoder } from './SlotGridDecoder';

/** Spin response 到 SlotRoundResult 的唯一轉換點 Handler／Task／Controller 不得直接讀 SlotApiSpinResponse */
export class SlotRoundMapper {
    private readonly gridDecoder = new SlotGridDecoder();

    constructor(private readonly layout: SlotGridLayout) {}

    toSlotRoundResult(response: SlotApiSpinResponse): SlotRoundResult {
        return {
            operationId: response.operation_id,
            betId: response.bet_id,
            totalWin: response.total_win,
            rawEngineWin: response.raw_engine_win ?? response.total_win,
            engineWin: response.engine_win ?? response.total_win,
            maxWin: {
                applied: response.max_win?.applied ?? false,
                multiplier: response.max_win?.multiplier ?? '',
                capAmount: response.max_win?.cap_amount ?? '',
            },
            balanceAfter: response.balance_after,
            outcome: response.outcome,
            freeRound: response.free_round,
            chargedWager: response.charged_wager,
            jackpot: this.toSlotJackpotResult(response),
            ...this.toRoundSteps(response.round_result),
            multiplier: response.multiplier ?? response.round_result.Multiplier,
            freeSpinTriggered: response.free_game_triggered ?? response.round_result.FreeGameTriggered,
        };
    }

    /** Grid／Awards／Free 局的解碼邏輯，跟「這是哪次 spin」無關，History Detail 沒有 spin 信封欄位時也能重用 */
    toRoundSteps(roundResult: SlotApiRoundResult): SlotRoundSteps {
        return {
            mainSteps: roundResult.Main.map((step) => this.toSlotRoundStep(step)),
            freeRounds: (roundResult.Free ?? []).map((round) => round.map((step) => this.toSlotRoundStep(step))),
            freeSpinTriggered: roundResult.FreeGameTriggered,
            freeMultipliers: (roundResult.FreeMultipliers ?? []).map((m) => this.toSlotFreeMultiplierStep(m)),
            multiplier: roundResult.Multiplier,
        };
    }

    private toSlotRoundStep(step: SlotApiStep): SlotRoundStep {
        const grid = this.gridDecoder.decode({ columns: step.Grid.Cols, rows: step.Grid.Rows, cells: step.Grid.Cells }, this.layout);

        return {
            grid,
            awards: (step.Awards ?? []).map((award) => this.toSlotAward(award)),
            win: step.Win,
        };
    }

    private toSlotAward(award: SlotApiAward): SlotAward {
        return {
            symbolId: Number(award.SymbolID),
            count: award.Count,
            positions: award.Positions.map(([col, row]) => this.toSlotAwardPosition(col, row)),
            pay: award.Pay,
        };
    }

    /** 正式座標直接是可視 row 舊回放含前置 buffer 時才需要偏移 */
    private toSlotAwardPosition(col: number, row: number): SlotAwardPosition {
        const rowOffset = this.layout.bufferPlacement === 'start' ? this.layout.bufferRows : 0;
        return { col, row: row - rowOffset };
    }

    private toSlotFreeMultiplierStep(multiplier: SlotApiFreeMultiplier): SlotFreeMultiplierStep {
        return {
            round: multiplier.round,
            multiplier: multiplier.mult,
            accumulated: multiplier.acc,
            win: multiplier.win,
        };
    }

    private toSlotJackpotResult(response: SlotApiSpinResponse): SlotJackpotResult {
        if (!response.jackpot) return { won: false, tier: '', payout: '0', currency: '' };
        return {
            won: response.jackpot.won,
            tier: toSlotJackpotTier(response.jackpot.tier),
            payout: response.jackpot.payout,
            currency: response.jackpot.currency,
        };
    }
}

/** 後端 JP 等級 toLowerCase() */
function toSlotJackpotTier(tier: SlotApiJackpotTier | ''): SlotJackpotTier | '' {
    return tier === '' ? '' : (tier.toLowerCase() as SlotJackpotTier);
}
