import { _decorator, Component, instantiate, Label, Node } from 'cc';
import AppAssetBundle from '../../../core/base/utility/AppAssetBundle';
import { VIEWMAP } from '../../../core/framework/Runtime/Store/StoreMap';
import StoreManager from '../../../core/framework/Runtime/Store/StoreManager';
import GameConfigManager from '../../../core/framework/Runtime/GameConfigManager';
const { ccclass, property } = _decorator;

@ccclass('slot/1001/GameRuleView')
export class GameRuleView extends Component {
    @property(Node)
    N1: Node = null;
    @property(Node)
    N2: Node = null;
    @property(Node)
    N3: Node = null;
    @property(Node)
    N4: Node = null;
    @property(Node)
    N5: Node = null;
    @property(Node)
    A: Node = null;
    @property(Node)
    K: Node = null;
    @property(Node)
    Q: Node = null;
    @property(Node)
    J: Node = null;
    @property(Node)
    '10': Node = null;
    PAY_TABLE = [
        { symbol: 'N1', payouts: [{ count: '5', multiplier: 2 }, { count: '4', multiplier: 0.6 }, { count: '3', multiplier: 0.2 }, { count: '2', multiplier: 0.08 }] },
        { symbol: 'N2', payouts: [{ count: '5', multiplier: 2 }, { count: '4', multiplier: 0.4 }, { count: '3', multiplier: 0.2 }, { count: '2', multiplier: 0 }] },
        { symbol: 'N3', payouts: [{ count: '5', multiplier: 1.2 }, { count: '4', multiplier: 0.4 }, { count: '3', multiplier: 0.2 }, { count: '2', multiplier: 0 }] },
        { symbol: 'N4', payouts: [{ count: '5', multiplier: 1.2 }, { count: '4', multiplier: 0.4 }, { count: '3', multiplier: 0.2 }, { count: '2', multiplier: 0 }] },
        { symbol: 'N5', payouts: [{ count: '5', multiplier: 1.2 }, { count: '4', multiplier: 0.4 }, { count: '3', multiplier: 0.2 }, { count: '2', multiplier: 0 }] },
        { symbol: 'A', payouts: [{ count: '5', multiplier: 1.2 }, { count: '4', multiplier: 0.4 }, { count: '3', multiplier: 0.2 }, { count: '2', multiplier: 0 }] },
        { symbol: 'K', payouts: [{ count: '5', multiplier: 0.6 }, { count: '4', multiplier: 0.2 }, { count: '3', multiplier: 0.08 }, { count: '2', multiplier: 0 }] },
        { symbol: 'Q', payouts: [{ count: '5', multiplier: 0.6 }, { count: '4', multiplier: 0.2 }, { count: '3', multiplier: 0.08 }, { count: '2', multiplier: 0 }] },
        { symbol: 'J', payouts: [{ count: '5', multiplier: 0.6 }, { count: '4', multiplier: 0.2 }, { count: '3', multiplier: 0.08 }, { count: '2', multiplier: 0 }] },
        { symbol: '10', payouts: [{ count: '5', multiplier: 0.6 }, { count: '4', multiplier: 0.2 }, { count: '3', multiplier: 0.08 }, { count: '2', multiplier: 0 }] },
    ];
    contentList: Label[][] = Array.from({ length: 10 }, () => []);;
    protected override async start() {
        const storeManager = StoreManager.getInstance();
        const bet = storeManager.getModel('TemplateStore').betBalance;
        for (let key in this.PAY_TABLE) {
            for (let index in this.PAY_TABLE[key].payouts) {
                let payout = this.PAY_TABLE[key].payouts[index];
                const multiplier = payout.multiplier;
                if (multiplier === 0) continue; // 如果倍數為0，則跳過不顯示
                let title = instantiate(await AppAssetBundle.getInstance(GameConfigManager.GAMEID).loadPrefab(VIEWMAP.INFOVIEWTITLE.path));
                let content = instantiate(await AppAssetBundle.getInstance(GameConfigManager.GAMEID).loadPrefab(VIEWMAP.INFOVIEWCONTENT.path));
                let contentLabel = content.getComponent(Label);
                title.getComponent(Label).string = payout.count + ' - ';
                title.setPosition(30, - 30 - (Number(index) * 30))
                const result = Math.round(payout.multiplier * bet * 100) / 100;
                contentLabel.string = result.toFixed(2); content.setPosition(50, title.y);
                this.contentList[Number(key)][index] = contentLabel;
                this[this.PAY_TABLE[key].symbol].addChild(title);
                this[this.PAY_TABLE[key].symbol].addChild(content);
            };
        }
    }

    updateContent() {
        const storeManager = StoreManager.getInstance();
        const bet = storeManager.getModel('TemplateStore').betBalance;
        if (this.contentList[0].length === 0) return;
        for (let key in this.PAY_TABLE) {
            for (let index in this.PAY_TABLE[key].payouts) {
                const result = Math.round(this.PAY_TABLE[key].payouts[index].multiplier * bet * 100) / 100;
                // console.log("updateContent result = ", result);
                // console.log("updateContent contentList = ", this.contentList);
                // console.log("key = ", key);
                // console.log("updateContent result = ", this.contentList[Number(key)]);
                // console.log("index = ", index);
                // console.log("updateContent test = ", this.contentList[Number(key)][Number(index)]);
                const multiplier = this.PAY_TABLE[key].payouts[index].multiplier;
                if (multiplier === 0) continue; // 如果倍數為0，則跳過不顯示
                // 加上防呆
                if (!this.contentList[Number(key)]?.[Number(index)]) continue;
                this.contentList[Number(key)][Number(index)].string = result.toFixed(2);
            }
        }
    }
    protected override onEnable(): void {
        console.log("GameRuleView onEnable");
        this.updateContent();

    }

}

