import AppStore, { BaseModelType } from './AppStore'
import GameStore from '../../../slot/Store/SlotGameStore';
import UserStore from './UserStore';
import ViewStore from './ViewStore';
import TrackerStore from './TrackerStore';
import { DeviceStore } from './DeviceStore';

export default class StoreManager {
    public static instance;
    kystore: AppStore
    gamestore: GameStore = null;
    httpClientStore: any = null;
    userStore: UserStore = null;
    trackerStore: TrackerStore = null;
    deviceStore: DeviceStore = null;
    viewStore: ViewStore = null;

    constructor() {
        this.initStore();
        this.registerStore();
    }
    public static getInstance() {
        if (!StoreManager.instance) {
            StoreManager.instance = new StoreManager();
        }
        return StoreManager.instance;
    }
    initStore() {
        this.kystore = new AppStore();
        this.gamestore = new GameStore({});
        this.userStore = new UserStore({});
        this.viewStore = new ViewStore({});
        this.trackerStore = new TrackerStore({});
        this.deviceStore = new DeviceStore({});
    }

    setHttpClientStore(httpClientStore: any) {
        if (this.httpClientStore && this.httpClientStore !== httpClientStore) {
            this.httpClientStore.close?.();
        }
        this.httpClientStore = httpClientStore;
        this.kystore.registerModel(this.httpClientStore);
    }
    registerStore() {
        this.kystore.registerModel(this.gamestore);
        this.kystore.registerModel(this.userStore);
        this.kystore.registerModel(this.viewStore);
        this.kystore.registerModel(this.trackerStore);
        this.kystore.registerModel(this.deviceStore);
    }

    registerModel(model: BaseModelType): void {
        this.kystore.registerModel(model);
    }

    unregisterModel(model: BaseModelType): void {
        this.kystore.unregisterModel(model);
    }

    getModel(key): any {
        return this.kystore.models.get('store/' + key);
    }
    getGameStore(): any {
        return this.gamestore;
    }
    getHttpClientStore(): any {
        return this.httpClientStore;
    }
    getUserStore(): any {
        return this.userStore;
    }
    getDeviceStore(): DeviceStore {
        return this.deviceStore;
    }
    getViewStore(): any {
        return this.viewStore;
    }
    getTrackerStore(): any {
        return this.trackerStore;
    }
}
