/**
 * Logger.ts
 * 共用 Log 工具，支援：
 *  - Log 等級過濾（Debug / Info / Warn / Error）
 *  - Tag 分類
 *  - 時間戳記
 *  - 正式版（Release）自動關閉
 *
 * 使用方式：
 *   import { Logger } from './Logger';
 *   const log = new Logger('BaseButton');
 *   log.debug('初始化完成');
 *   log.info('按鈕狀態', ButtonState.Normal);
 *   log.warn('找不到子節點');
 *   log.error('嚴重錯誤', err);
 */

// ─── 等級定義 ─────────────────────────────────────────────────────

export enum LogLevel {
  Debug = 0,
  Info = 1,
  Warn = 2,
  Error = 3,
  Off = 4, // 完全關閉
}

// ─── 全域設定 ─────────────────────────────────────────────────────

export interface LoggerConfig {
  /** 最低輸出等級，低於此等級的 Log 會被忽略，預設 Debug */
  minLevel: LogLevel;
  /** 是否顯示時間戳記，預設 true */
  showTimestamp: boolean;
  /** 在正式版（!CC_DEBUG）自動關閉，預設 true */
  disableOnRelease: boolean;
  /** 要靜音的 Tag 清單（優先於 allowedTags） */
  mutedTags: string[];
  /** 白名單 Tag，設定後只輸出這些 Tag（空陣列 = 全部允許） */
  allowedTags: string[];
}

const _defaultConfig: LoggerConfig = {
  minLevel: LogLevel.Debug,
  showTimestamp: true,
  disableOnRelease: true,
  mutedTags: [],
  allowedTags: [],
};

// ─── 樣式（瀏覽器 / Cocos 預覽器支援 %c） ──────────────────────

const _style: Record<string, string> = {
  tag: "color:#7ecfff; font-weight:bold;",
  debug: "color:#b0b0b0;",
  info: "color:#6ddc8b;",
  warn: "color:#f0c040; font-weight:bold;",
  error: "color:#ff6b6b; font-weight:bold;",
  time: "color:#888888;",
};

// ─── Logger 類別 ──────────────────────────────────────────────────

export class Logger {
  // 全域共用設定，可在遊戲入口統一修改
  public static config: LoggerConfig = { ..._defaultConfig };

  /** 快捷：一次設定全域最低等級 */
  public static setLevel(level: LogLevel): void {
    Logger.config.minLevel = level;
  }

  /** 快捷：靜音指定 Tag */
  public static mute(...tags: string[]): void {
    Logger.config.mutedTags.push(...tags);
  }

  /** 快捷：只允許指定 Tag 輸出 */
  public static allow(...tags: string[]): void {
    Logger.config.allowedTags.push(...tags);
  }

  /** 重置為預設設定 */
  public static reset(): void {
    Logger.config = { ..._defaultConfig };
  }

  // ─── 實例 ────────────────────────────────────────────────────

  private readonly _tag: string;

  /**
   * @param tag 模組名稱，例如 'BaseButton'、'GameManager'
   */
  constructor(tag: string) {
    this._tag = tag;
  }

  public debug(...args: unknown[]): void {
    this._output(LogLevel.Debug, ...args);
  }

  public info(...args: unknown[]): void {
    this._output(LogLevel.Info, ...args);
  }

  public warn(...args: unknown[]): void {
    this._output(LogLevel.Warn, ...args);
  }

  public error(...args: unknown[]): void {
    this._output(LogLevel.Error, ...args);
  }

  // ─── 核心輸出 ─────────────────────────────────────────────────

  private _output(level: LogLevel, ...args: unknown[]): void {
    const cfg = Logger.config;

    // 正式版關閉
    // @ts-ignore CC_DEBUG 為 Cocos 全域常數
    if (cfg.disableOnRelease && typeof CC_DEBUG !== "undefined" && !CC_DEBUG)
      return;

    // 等級過濾
    if (level < cfg.minLevel) return;

    // Tag 白名單 / 黑名單
    if (cfg.allowedTags.length > 0 && !cfg.allowedTags.includes(this._tag))
      return;
    if (cfg.mutedTags.includes(this._tag)) return;

    const { label, style, consoleFn } = _levelMeta(level);
    const time = cfg.showTimestamp ? `[${_timestamp()}] ` : "";
    const tag = `[${this._tag}]`;

    // 使用 %c 彩色輸出（Cocos 預覽器 / Chrome DevTools 支援）
    consoleFn(
      `%c${time}%c${tag} %c${label}`,
      _style.time,
      _style.tag,
      style,
      ...args,
    );
  }
}

// ─── 輔助函式 ─────────────────────────────────────────────────────

function _timestamp(): string {
  const d = new Date();
  const hh = String(d.getHours()).padStart(2, "0");
  const mm = String(d.getMinutes()).padStart(2, "0");
  const ss = String(d.getSeconds()).padStart(2, "0");
  const ms = String(d.getMilliseconds()).padStart(3, "0");
  return `${hh}:${mm}:${ss}.${ms}`;
}

function _levelMeta(level: LogLevel): {
  label: string;
  style: string;
  consoleFn: (...args: unknown[]) => void;
} {
  switch (level) {
    case LogLevel.Debug:
      return { label: "[DEBUG]", style: _style.debug, consoleFn: console.log };
    case LogLevel.Info:
      return { label: "[INFO] ", style: _style.info, consoleFn: console.info };
    case LogLevel.Warn:
      return { label: "[WARN] ", style: _style.warn, consoleFn: console.warn };
    case LogLevel.Error:
      return {
        label: "[ERROR]",
        style: _style.error,
        consoleFn: console.error,
      };
    default:
      return { label: "[LOG]  ", style: "", consoleFn: console.log };
  }
}
