import { _decorator, Component, Node, NodePool, Prefab, ScrollView, UITransform, Vec2, Vec3, instantiate } from 'cc';
import { EventComponent } from '../../../base/EventComponent/EventComponent';
import { computeVisibleRange } from './VirtualListMath';

const { ccclass, property } = _decorator;

/** item 節點上要掛的元件必須實作這個介面，VirtualList 只透過它跟具體 item 互動 */
export interface ListItemView<TData> extends Component {
    /** index 是 0-based 陣列索引（標準 JS 慣例）；要 1-based 顯示編號由呼叫端自己的 data 決定，這裡不做轉換 */
    bind(data: TData, index: number): void;
}

/**
 * VirtualList（虛擬化清單，泛型、跟資料型別無關）
 *
 * entry 目前沒有現成的虛擬化清單元件（`AppViewPool` 是彈窗級節點池，語意不同，
 * 不能直接借）。這裡新建一份通用版本，不綁死桌位清單——未來歷史紀錄／排行榜等
 * 清單也能直接重用。對應舊專案 `ListView`/`ListAdapter` 的節點回收模式，但用
 * entry 慣用的 Component + `NodePool` 實作，不套用 Adapter 抽象類別那套。
 *
 * 支援網格排版：`columnCount` 設 >1 時自動每行排幾個、超過自動換行（見
 * `spacingX`/`spacingY` 調整間距）；`columnCount=1`（預設）等同單欄清單。
 *
 * **假設與驗證狀態**：目前實作假設「由上而下排列、`content` 的
 * `UITransform.anchorY` 為 1（頂部對齊）、`anchorX` 為 0.5（水平置中，
 * Cocos ScrollView content 的標準預設值）」，這是常見但不是唯一的佈局慣例；
 * item prefab 本身的 anchor 不做假設，`positionItem()` 會讀取每個 item 實際的
 * anchorX/anchorY 自動補償定位。第一版實機驗證（2026-08-11，單欄模式）發現
 * 兩個問題並已修正：
 * ① `viewHeight`／捲動偏移量不該自己解讀 `scrollView.node` 的 UITransform／
 * `content.position`（後者初始值不是 0，`scrollView.node` 的 UITransform 也不
 * 等於實際 viewport 大小），改用 `ScrollView.getScrollOffset()`／`ScrollView.view`
 * 官方 API；② item 定位原本寫死假設 item anchorY=1，若 item prefab 的 anchor
 * 不是 1（例如常見的置中 0.5），每個 item 只有一半落在可視窗口內，另一半被
 * Mask 裁掉，看起來就像完全沒有渲染——已改成讀取 item 實際 anchorY 補償。
 *
 * **Item prefab 注意事項（2026-08-11 實測踩坑）**：`instantiate(itemPrefab)`
 * 產生的節點，`layer` 是照 prefab 資產本身存的原始值，不會像在 Editor 裡手動
 * 把節點拖進 Canvas 底下那樣被自動修正——如果 item prefab 的根節點 `Layer`
 * 沒設成跟 Canvas/UI 一致（例如還是預設的 `Default`），Camera 的 `visibility`
 * 遮罩不會涵蓋到它，节點會正常建立、位置也正確，但完全不會被渲染出來，
 * 且沒有任何 Console 錯誤/警告可以提示這件事。**每個 item prefab 的根節點
 * Layer 務必手動確認跟其他能正常顯示的 UI 元素一致（通常是 `UI_2D`）**。
 *
 * **網格模式（`columnCount>1`）尚未在 Editor 裡實機驗證過**——目前只有單欄
 * 模式（`columnCount=1`）跑過上面提到的實機驗證流程。X 軸置中定位公式、
 * `resizeContent()` 的多行高度計算都只憑推導與純數學驗證（見
 * `.claude-workspace/scripts/verify-virtual-list-math.ts`），套用網格排版前
 * 務必先實機測一次（含 `spacingX`/`spacingY` 是否符合預期、換行邊界是否正確）。
 */
@ccclass('slot/1001/core/framework/VirtualList')
export class VirtualList<TData> extends EventComponent {
    @property(ScrollView)
    protected scrollView: ScrollView = null!;

    @property(Prefab)
    protected itemPrefab: Prefab = null!;

    @property({ tooltip: '單一 item 的高度（不含間距）' })
    protected itemHeight: number = 100;

    @property({ tooltip: '單一 item 的寬度（不含間距）；columnCount=1 時不影響定位，仍建議填寫' })
    protected itemWidth: number = 100;

    @property({ tooltip: '每行幾個 item，1=單欄清單（預設，等同原本行為），>1 超過自動換行排成網格' })
    protected columnCount: number = 1;

    @property({ tooltip: '同一行內，item 與 item 之間的水平間距' })
    protected spacingX: number = 0;

    @property({ tooltip: '列與列之間的垂直間距' })
    protected spacingY: number = 0;

    @property({ tooltip: '可視範圍上下各多保留幾「行」已實體化的 item，減少快速捲動時的邊緣閃爍/重新綁定' })
    protected bufferCount: number = 2;

    private readonly pool = new NodePool();
    private readonly activeNodes = new Map<number, Node>();
    private data: TData[] = [];

    protected override onLoad(): void {
        // 場景整批銷毀時，ScrollView 所在節點可能先於這個元件被銷毀——node 參照
        // 本身不會變成 null，但底層物件已失效，單純 null 檢查攔不到，要用
        // isValid 判斷（TableListItemView.ts 也踩過同一個坑）。
        this.trackDisposer(() => {
            if (this.scrollView?.node?.isValid) this.scrollView.node.off(ScrollView.EventType.SCROLLING, this.onScrolling, this);
        });
        this.scrollView.node.on(ScrollView.EventType.SCROLLING, this.onScrolling, this);
    }

    public override onDestroy(): void {
        super.onDestroy();
        this.clearActive();
        this.pool.clear();
    }

    setData(data: TData[]): void {
        this.data = data;
        this.resizeContent();
        this.refreshVisible();
    }

    /** 強制整批重新綁定目前可視範圍（資料內容有變但筆數不變時使用，例如統計數字更新） */
    refresh(): void {
        for (const [index, node] of this.activeNodes) {
            this.bindItem(node, index);
        }
    }

    /**
     * 捲動到讓指定 index 所在的行進入可視範圍。已經在可視範圍內就不動；
     * 否則捲到該行對齊可視範圍頂部，並 clamp 在有效捲動範圍內。
     */
    scrollToIndex(index: number, timeInSecond: number = 0.2): void {
        if (index < 0 || index >= this.data.length) return;

        const rowPitch = this.itemHeight + this.spacingY;
        if (rowPitch <= 0) return;
        const row = Math.floor(index / this.columnCount);
        const targetOffsetY = row * rowPitch;

        const viewTransform = this.scrollView.view?.getComponent(UITransform) ?? this.scrollView.node.getComponent(UITransform);
        const viewHeight = viewTransform ? viewTransform.height : 0;
        const contentTransform = this.scrollView.content?.getComponent(UITransform);
        const maxOffsetY = contentTransform ? Math.max(0, contentTransform.height - viewHeight) : targetOffsetY;

        const currentOffsetY = this.scrollView.getScrollOffset().y;
        if (targetOffsetY >= currentOffsetY && targetOffsetY + rowPitch <= currentOffsetY + viewHeight) return;

        const clampedOffsetY = Math.min(Math.max(0, targetOffsetY), maxOffsetY);
        this.scrollView.scrollToOffset(new Vec2(0, clampedOffsetY), timeInSecond);
    }

    private resizeContent(): void {
        const content = this.scrollView.content;
        if (!content) return;
        const transform = content.getComponent(UITransform);
        if (!transform) return;
        const totalRows = Math.ceil(this.data.length / this.columnCount);
        transform.height = totalRows * (this.itemHeight + this.spacingY);
    }

    private onScrolling(): void {
        this.refreshVisible();
    }

    private refreshVisible(): void {
        const content = this.scrollView.content;
        if (!content || this.data.length === 0) {
            this.clearActive();
            return;
        }

        // 用 ScrollView 官方 API 取得真正的 viewport 尺寸／捲動偏移，不要自己解讀
        // content.position／scrollView.node 的 UITransform——scrollView.node 是整個
        // ScrollView 節點，UITransform 高度不等於實際可視窗口（view/Mask 子節點）的高度；
        // content.position 的初始值也不是 0（Cocos 標準 ScrollView 建立時，content
        // anchorY=1 對齊 view 頂部需要一個非零初始位移，等於 view 高度的一半），
        // 兩者都曾經是這份骨架的實作 bug，改用 getScrollOffset()／view 才是跟
        // anchor／初始 position 無關的正確讀法。
        const viewTransform = this.scrollView.view?.getComponent(UITransform) ?? this.scrollView.node.getComponent(UITransform);
        const viewHeight = viewTransform ? viewTransform.height : 0;
        const scrollOffsetY = this.scrollView.getScrollOffset().y;

        const { startIndex, endIndex } = computeVisibleRange({
            scrollOffsetY,
            viewHeight,
            itemHeight: this.itemHeight,
            spacingY: this.spacingY,
            columnCount: this.columnCount,
            bufferCount: this.bufferCount,
            dataLength: this.data.length,
        });

        // 回收超出範圍的 item
        for (const [index, node] of this.activeNodes) {
            if (index < startIndex || index > endIndex) {
                this.activeNodes.delete(index);
                this.pool.put(node);
            }
        }

        // 補齊範圍內尚未實體化的 item
        for (let index = startIndex; index <= endIndex; index++) {
            if (this.activeNodes.has(index)) continue;
            const node = this.pool.size() > 0 ? this.pool.get()! : instantiate(this.itemPrefab);
            content.addChild(node);
            this.positionItem(node, index);
            this.activeNodes.set(index, node);
            this.bindItem(node, index);
        }
    }

    /**
     * 定位單一 item（網格排版：row = index / columnCount 取整，col = index % columnCount）。
     * 不假設 item prefab 的 anchor 一定是 (0.5, 1)，而是讀取它實際的 anchorX/anchorY
     * 去補償，讓每個 item 不管自己的 pivot 在哪都能對齊到它該佔的那個格子。
     *
     * Y 軸：假設 content 本身 anchorY=1（頂部對齊）。row 的視覺頂部
     * = -row*(itemHeight+spacingY)（相對 content 座標系）。item 視覺頂部
     * = position.y + (1-anchorY)*itemHeight，兩者相等解出 position.y。
     *
     * X 軸：假設 content 本身 anchorX=0.5（水平置中，Cocos ScrollView content 的
     * 標準預設值）。整行以 x=0 為中心排列，col 的格子中心
     * = (col - (columnCount-1)/2) * (itemWidth+spacingX)。item 視覺左緣
     * = position.x - anchorX*itemWidth，格子左緣 = 格子中心 - itemWidth/2，
     * 兩者相等解出 position.x = 格子中心 + (anchorX-0.5)*itemWidth。
     */
    private positionItem(node: Node, index: number): void {
        const transform = node.getComponent(UITransform);
        const anchorX = transform ? transform.anchorX : 0.5;
        const anchorY = transform ? transform.anchorY : 1;

        const row = Math.floor(index / this.columnCount);
        const col = index % this.columnCount;

        const rowTopY = -row * (this.itemHeight + this.spacingY);
        const positionY = rowTopY - (1 - anchorY) * this.itemHeight;

        const cellCenterX = (col - (this.columnCount - 1) / 2) * (this.itemWidth + this.spacingX);
        const positionX = cellCenterX + (anchorX - 0.5) * this.itemWidth;

        node.setPosition(new Vec3(positionX, positionY, 0));
    }

    private bindItem(node: Node, index: number): void {
        const data = this.data[index];
        if (data === undefined) return;
        this.findItemView(node)?.bind(data, index);
    }

    /** interface 沒有 Cocos 註冊名稱可查，掃節點上第一個實作 bind() 的元件當作 ListItemView */
    private findItemView(node: Node): ListItemView<TData> | null {
        for (const comp of node.components) {
            if (typeof (comp as Partial<ListItemView<TData>>).bind === 'function') return comp as ListItemView<TData>;
        }
        return null;
    }

    private clearActive(): void {
        // 場景整批銷毀時，item 節點可能已經隨父層一起被銷毀，只回收還有效的
        for (const node of this.activeNodes.values()) {
            if (node.isValid) this.pool.put(node);
        }
        this.activeNodes.clear();
    }
}
