import { _decorator, Node, profiler } from 'cc';
import GameSceneViewModel from '../../core/framework/GameScene/GameSceneViewModel';
import AppConfig from '../../core/framework/Runtime/Config/AppConfig';
import { EventComponent } from '../../core/base/EventComponent/EventComponent';
import type { TypedEventBus } from '../../core/base/EventComponent/TypedEventBus';
import { PopupManager } from '../../core/framework/View/PopupView/Base/PopupManager';
import { createRootStore } from '../../core/base/store/RootStoreHooks';
const { ccclass, property } = _decorator;
@ccclass('slot/1001/GameScene')
export class GameScene extends EventComponent {
    /** EventComponent.subscribeEvent 是 protected，這裡轉一層 public 供 GameSceneViewModel 呼叫 */
    public subscribeGameEvent<TEvents extends object, K extends keyof TEvents>(
        bus: TypedEventBus<TEvents>,
        type: K,
        handler: (payload: TEvents[K]) => void
    ): void {
        this.subscribeEvent(bus, type, handler);
    }

    @property(Node)
    staticNode: Node;

    @property(Node)
    gameNode: Node;

    @property(Node)
    templateNode: Node;

    @property(Node)
    middleNode: Node;

    @property(Node)
    topNode: Node;

    @property(Node)
    loadingView: Node;

    viewModel: GameSceneViewModel;

    private static readonly TOP_LAYER = 4;

    protected override onLoad(): void {
        console.log('GameScene onLoad');
        // slot_game 獨立專案沒有 entry lobby 的 LoadingScene 幫忙建立 RootStore
        // 這裡自己補一次 createRootStore 內部已做過重複呼叫防呆
        createRootStore();
        this.trackLayer(this.topNode, GameScene.TOP_LAYER);
        PopupManager.setLayer(this.topNode);
    }
    protected override start() {
        console.log('GameScene onStart');
        // 關閉 FPS 顯示
        if (!AppConfig.DEBUG) profiler.hideStats();
        // profiler.showStats();
        this.viewModel = new GameSceneViewModel(this);
    }

    private trackLayer(root: Node, layer: number): void {
        const apply = (n: Node) => {
            n.layer = layer;
            n.on(Node.EventType.CHILD_ADDED, (child: Node) => {
                this.setLayerRecursive(child, layer);
                apply(child);
            });
            for (const c of n.children) apply(c);
        };
        apply(root);
    }

    private setLayerRecursive(node: Node, layer: number): void {
        node.layer = layer;
        for (const c of node.children) this.setLayerRecursive(c, layer);
    }

    addGameNode(view) {
        if (!this.gameNode) {
            console.warn('[GameScene] gameNode null, skip addGameNode');
            return;
        }
        this.gameNode.addChild(view);
    }

    addTemplateNode(view) {
        if (!this.templateNode) {
            console.warn('[GameScene] templateNode null, skip addTemplateNode');
            return;
        }
        this.templateNode.addChild(view);
    }

    addMiddleNode(view) {
        if (!this.middleNode) {
            console.warn('[GameScene] middleNode null, skip addMiddleNode');
            return;
        }
        this.middleNode.addChild(view);
    }

    addTopNode(view) {
        if (!this.topNode) {
            console.warn('[GameScene] topNode null, skip addTopNode');
            return;
        }
        this.topNode.addChild(view);
    }

    deleteView(viewName) {
        const containers = [this.node, this.gameNode, this.templateNode, this.middleNode, this.topNode];

        let found = false;
        for (const container of containers) {
            for (let i = container.children.length - 1; i >= 0; i--) {
                if (container.children[i].name === viewName) {
                    container.children[i].destroy();
                    found = true;
                }
            }
        }
        if (!found) console.warn(`[removeView] 找不到節點: ${viewName}`);
    }
}
