import AppAudio from '../../core/base/audio/AppAudio';
import { GameState } from '../../core/framework/Framework/Component/GameState';
import { GameStateKey } from '../../core/slot/Framework/Component/GameStateKey';
import type { GameMain_1001 } from '../GameMain_1001';
import { MUSICMAP } from '../AudioConfig';

/**
 * 免費遊戲狀態（比照舊專案 SGState_FG，本體維持空殼——實際的進場/離場 side effect
 * 由 EnterFreeGameTask/ExitFreeGameTask 負責，changeState() 只是流程中的一步）。
 */
export class FGState_1001 extends GameState<GameMain_1001> {
    protected override onEnter(): void {
        const audio = AppAudio.getInstance();
        audio.stopMusic();
        audio.playMusic(MUSICMAP.FREEGAME, 0);
        audio.playMusic(MUSICMAP.BACKGROUND, 1);

        // 存進 GameStore.gameMode
        this.game.storeManager.getGameStore().setGameMode(GameStateKey.FG);
    }
}
