import type { ReelTimingOverride, ReelTimingTier } from '../../core/framework/Runtime/Config/ReelTimingDebugStore';

// reelConfig.json 的路徑（bundle 相對路徑，不含副檔名）
export const REEL_CONFIG_PATH = 'resources/jsons/reelConfig';

// 對應 cc.TweenEasing 的合法字串清單，這裡刻意不 import cc 保持這份檔案跟引擎解耦
const VALID_EASE_NAMES = new Set([
    'linear', 'smooth', 'fade', 'constant',
    'quadIn', 'quadOut', 'quadInOut', 'quadOutIn',
    'cubicIn', 'cubicOut', 'cubicInOut', 'cubicOutIn',
    'quartIn', 'quartOut', 'quartInOut', 'quartOutIn',
    'quintIn', 'quintOut', 'quintInOut', 'quintOutIn',
    'sineIn', 'sineOut', 'sineInOut', 'sineOutIn',
    'expoIn', 'expoOut', 'expoInOut', 'expoOutIn',
    'circIn', 'circOut', 'circInOut', 'circOutIn',
    'elasticIn', 'elasticOut', 'elasticInOut', 'elasticOutIn',
    'backIn', 'backOut', 'backInOut', 'backOutIn',
    'bounceIn', 'bounceOut', 'bounceInOut', 'bounceOutIn',
]);

// 三段速度預設值，跟 jsons/reelConfig.json（PM 目前調整完的節奏，2026-08-19）一致
const DEFAULT_TIERS: [ReelTimingTier, ReelTimingTier, ReelTimingTier] = [
    { tumbleClear: 0.2, tumbleFill: 0.3, tumbleClearEase: 'cubicIn', tumbleFillEase: 'cubicIn', explode: 0.3, winFx: 1.6, fill: 0.2, fillStagger: 0.04, fillEase: 'quadIn' },
    { tumbleClear: 0.15, tumbleFill: 0.2, tumbleClearEase: 'cubicIn', tumbleFillEase: 'cubicIn', explode: 0.24, winFx: 1.3, fill: 0.12, fillStagger: 0.024, fillEase: 'quadIn' },
    { tumbleClear: 0.1, tumbleFill: 0.1, tumbleClearEase: 'cubicIn', tumbleFillEase: 'cubicIn', explode: 0.08, winFx: 1.0, fill: 0.03, fillStagger: 0, fillEase: 'quadIn' },
];

export const DEFAULT_REEL_CONFIG: ReelTimingOverride = {
    beginDuration: 0.3,
    loopTime: 0.04,
    endDuration: 0.15,
    beginEase: 'linear',
    endEase: 'linear',
    tiers: DEFAULT_TIERS,
};

function parseTier(raw: unknown, fallback: ReelTimingTier): ReelTimingTier {
    const tier: ReelTimingTier = { ...fallback };
    const obj = raw as Partial<Record<keyof ReelTimingTier, unknown>> | null;
    if (!obj) return tier;

    if (typeof obj.tumbleClear === 'number') tier.tumbleClear = obj.tumbleClear;
    if (typeof obj.tumbleFill === 'number') tier.tumbleFill = obj.tumbleFill;
    if (typeof obj.tumbleClearEase === 'string' && VALID_EASE_NAMES.has(obj.tumbleClearEase)) tier.tumbleClearEase = obj.tumbleClearEase;
    if (typeof obj.tumbleFillEase === 'string' && VALID_EASE_NAMES.has(obj.tumbleFillEase)) tier.tumbleFillEase = obj.tumbleFillEase;
    if (typeof obj.explode === 'number') tier.explode = obj.explode;
    if (typeof obj.winFx === 'number') tier.winFx = obj.winFx;
    if (typeof obj.fill === 'number') tier.fill = obj.fill;
    if (typeof obj.fillStagger === 'number') tier.fillStagger = obj.fillStagger;
    if (typeof obj.fillEase === 'string' && VALID_EASE_NAMES.has(obj.fillEase)) tier.fillEase = obj.fillEase;

    return tier;
}

/** 解析 reelConfig.json，格式不對的欄位（或整段 tier）保留預設值，不整份丟棄 */
export function parseReelConfig(raw: unknown): ReelTimingOverride {
    const cfg: ReelTimingOverride = { ...DEFAULT_REEL_CONFIG, tiers: [...DEFAULT_TIERS] as [ReelTimingTier, ReelTimingTier, ReelTimingTier] };
    const obj = raw as Partial<Record<keyof ReelTimingOverride, unknown>> | null;
    if (!obj) return cfg;

    if (typeof obj.beginDuration === 'number') cfg.beginDuration = obj.beginDuration;
    if (typeof obj.loopTime === 'number') cfg.loopTime = obj.loopTime;
    if (typeof obj.endDuration === 'number') cfg.endDuration = obj.endDuration;
    if (typeof obj.beginEase === 'string' && VALID_EASE_NAMES.has(obj.beginEase)) cfg.beginEase = obj.beginEase;
    if (typeof obj.endEase === 'string' && VALID_EASE_NAMES.has(obj.endEase)) cfg.endEase = obj.endEase;

    const rawTiers = obj.tiers;
    if (Array.isArray(rawTiers)) {
        cfg.tiers = [parseTier(rawTiers[0], DEFAULT_TIERS[0]), parseTier(rawTiers[1], DEFAULT_TIERS[1]), parseTier(rawTiers[2], DEFAULT_TIERS[2])];
    }

    return cfg;
}
